fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let ndx = [40, 37, 28, 15, 0, -15, -28, -37, -40, -37, -28, -15, 0, 15, 28, 37];
    let ndy = [0, 15, 28, 37, 40, 37, 28, 15, 0, -15, -28, -37, -40, -37, -28, -15];
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(3);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut v: i32 = host::display::state_get(0);
    let mut grab: i32 = host::display::state_get(1);
    if down == 1 && prev == 0 {
        let dx: i32 = px - cx;
        let dy: i32 = py - cy;
        if dx * dx + dy * dy <= 3600 {
            grab = 1;
            host::display::state_set(2, py);
        }
    }
    if down == 0 { grab = 0; }
    if grab == 1 {
        let lasty: i32 = host::display::state_get(2);
        v = v + (lasty - py);
        if v < 0 { v = 0; }
        if v > 127 { v = 127; }
        host::display::state_set(0, v);
        host::display::state_set(2, py);
    }
    host::display::state_set(1, grab);
    host::display::state_set(3, down);
    host::display::clear(0x101010);
    let mut row: i32 = -40;
    while row <= 40 {
        let rem: i32 = 1600 - row * row;
        let mut hw: i32 = 0;
        while (hw + 1) * (hw + 1) <= rem {
            hw = hw + 1;
        }
        host::display::fill_rect(cx - hw, cy + row, hw * 2 + 1, 1, 0x303038);
        row = row + 1;
    }
    let idx: i32 = v * 15 / 127;
    host::display::draw_line(cx, cy, cx + ndx[idx], cy - ndy[idx], 0x00ff88);
    host::display::draw_string(8, 8, "DRAG KNOB UP OR DOWN", 0x808080, 1);
    host::display::draw_number(8, 24, v, 0xffffff, 2);
    host::display::present();
}
